func TestRunDryRunWithoutCredentials(t *testing.T) {
	var stdout, stderr bytes.Buffer
	code := run(context.Background(), env(map[string]string{
		"SEMREL_VERSION": "v1.2.3",
		"SEMREL_DRY_RUN": "true",
	}), &stdout, &stderr)
	if code != 0 {
		t.Fatalf("expected exit code 0 in dry-run without credentials, got %d (stderr=%q)", code, stderr.String())
	}
	if !strings.Contains(stderr.String(), "[dry-run] hook-matrix: would need SEMREL_PLUGIN_HOMESERVER_URL, SEMREL_PLUGIN_TOKEN, SEMREL_PLUGIN_ROOM_ID to send notification") {
		t.Fatalf("expected missing credentials warning on stderr, got %q", stderr.String())
	}
	var payload plugin.MatrixContent
	if err := json.Unmarshal(stdout.Bytes(), &payload); err != nil {
		t.Fatalf("unmarshal dry-run payload: %v", err)
	}
	if payload.Destination != "<unset>" || payload.AccessToken != "<unset>" || payload.RoomID != "<unset>" {
		t.Fatalf("unexpected dry-run payload: %+v", payload)
	}
}

